public boolean removeSong() {
    if (songCount_ <= 0) {
        return false;
    }
    songCount_--;
    return true;
}

public boolean withdraw(double amount) {
    if (amount <= 0 || amount > balance_) {
        return false;
    }
    balance_ -= amount;
    return true;
}

public boolean moveSongTo(Playlist other) {
    if (!removeSong()) {
        return false;
    }
    other.addSong();
    return true;
}

public boolean transfer(BankAccount recipient, double amount) {
    if (!withdraw(amount)) {
        return false;
    }
    recipient.deposit(amount);
    return true;
}
